ALTER TABLE public.vendors OWNER TO slms_admin;

--
-- Name: v_customs_services; Type: VIEW; Schema: public; Owner: slms_admin
--

CREATE VIEW public.v_customs_services AS
 SELECT js.svc_id,
    js.job_id,
    j.job_no,
    js.service_type_code,
    mst.name_vi AS service_name,
    c.short_name AS customer,
    c.customer_code,
    js.vendor_id,
    v.short_name AS vendor_name,
    js.employee_id,
    e.short_name AS employee_name,
    COALESCE(v.short_name, e.short_name, 'Chưa gán'::character varying) AS assigned_to,
        CASE
            WHEN (js.vendor_id IS NOT NULL) THEN 'VENDOR'::text
            WHEN (js.employee_id IS NOT NULL) THEN 'EMPLOYEE'::text
            ELSE 'UNASSIGNED'::text
        END AS assignment_type,
    js.scheduled_date,
    js.declaration_no,
    js.declaration_datetime,
    js.loai_hinh,
    js.customs_type,
    js.customs_port,
    js.buyer_name,
    js.seller_name,
    js.hs_code,
    js.bl_awb_no,
    js.co_no,
    js.status_code,
    js.created_at
   FROM (((((public.job_services js
     JOIN public.jobs j ON ((js.job_id = j.job_id)))
     JOIN public.customers c ON ((j.customer_id = c.customer_id)))
     LEFT JOIN public.vendors v ON ((js.vendor_id = v.vendor_id)))
     LEFT JOIN public.employees e ON ((js.employee_id = e.employee_id)))
     LEFT JOIN public.master_service_types mst ON (((js.service_type_code)::text = (mst.service_code)::text)))
  WHERE ((js.service_type_code)::text = ANY ((ARRAY['CUS_IMPORT'::character varying, 'CUS_EXPORT'::character varying, 'CUS_TRANSIT'::character varying])::text[]));


ALTER VIEW public.v_customs_services OWNER TO slms_admin;

--
-- Name: v_drivers_tambao; Type: VIEW; Schema: public; Owner: slms_admin
--

CREATE VIEW public.v_drivers_tambao AS
 SELECT d.driver_id,
    d.driver_code,
    d.employee_id AS "Mã NV",
    d.full_name AS "Họ và tên",
    d.phone AS "SĐT",
    d.id_card AS "CCCD",
    d.license_plate AS "Biển số xe",
    v.company_name AS "Nhà vận chuyển",
    d.is_active AS "Hoạt động"
   FROM (public.drivers d
     LEFT JOIN public.vendors v ON ((d.vendor_id = v.vendor_id)))
  WHERE ((v.vendor_code)::text = 'TAMBAO'::text)
  ORDER BY d.driver_code;


ALTER VIEW public.v_drivers_tambao OWNER TO slms_admin;

--
-- Name: v_jobs_overview; Type: VIEW; Schema: public; Owner: slms_admin
--

CREATE VIEW public.v_jobs_overview AS
 SELECT j.job_id,
    j.job_no,
    c.short_name AS customer,
    j.description,
    j.status_code,
    j.etd,
    j.total_revenue,
    j.total_cost,
    ( SELECT count(*) AS count
           FROM public.job_services js
          WHERE (js.job_id = j.job_id)) AS services_count,
    ( SELECT array_agg(DISTINCT js.service_type_code) AS array_agg
           FROM public.job_services js
          WHERE (js.job_id = j.job_id)) AS service_types,
    j.created_at
   FROM (public.jobs j
     JOIN public.customers c ON ((j.customer_id = c.customer_id)))
  ORDER BY j.created_at DESC;


ALTER VIEW public.v_jobs_overview OWNER TO slms_admin;

--
-- Name: v_packing_services; Type: VIEW; Schema: public; Owner: slms_admin
--

CREATE VIEW public.v_packing_services AS
 SELECT js.svc_id,
    js.job_id,
    j.job_no,
    js.service_type_code,
    mst.name_vi AS service_name,
    c.short_name AS customer,
    c.customer_code,
    js.vendor_id,
    v.short_name AS vendor_name,
    js.employee_id,
    e.short_name AS employee_name,
    COALESCE(v.short_name, e.short_name, 'Chưa gán'::character varying) AS assigned_to,
        CASE
            WHEN (js.vendor_id IS NOT NULL) THEN 'VENDOR'::text
            WHEN (js.employee_id IS NOT NULL) THEN 'EMPLOYEE'::text
            ELSE 'UNASSIGNED'::text
        END AS assignment_type,
    js.scheduled_date,
    js.cargo_type,
    js.package_quantity,
    js.weight_kg,
    js.packing_type,
    js.items_count,
    js.packages_output,
    js.before_length_cm,
    js.before_width_cm,
    js.before_height_cm,
    js.after_length_cm,
    js.after_width_cm,
    js.after_height_cm,
    js.shrink_wrap,
    js.vacuum_pack,
    js.lashing,
    js.fumigation,
    js.status_code,
    js.created_at
   FROM (((((public.job_services js
     JOIN public.jobs j ON ((js.job_id = j.job_id)))
     JOIN public.customers c ON ((j.customer_id = c.customer_id)))
     LEFT JOIN public.vendors v ON ((js.vendor_id = v.vendor_id)))
     LEFT JOIN public.employees e ON ((js.employee_id = e.employee_id)))
     LEFT JOIN public.master_service_types mst ON (((js.service_type_code)::text = (mst.service_code)::text)))
  WHERE ((js.service_type_code)::text = ANY ((ARRAY['SVC_PACK'::character varying, 'SVC_VACUUM'::character varying, 'SVC_LASHING'::character varying, 'SVC_FUMI'::character varying])::text[]));


ALTER VIEW public.v_packing_services OWNER TO slms_admin;

--
-- Name: v_trucking_services; Type: VIEW; Schema: public; Owner: slms_admin
--

CREATE VIEW public.v_trucking_services AS
 SELECT js.svc_id,
    js.job_id,
    j.job_no,
    js.service_type_code,
    mst.name_vi AS service_name,
    c.short_name AS customer,
    c.customer_code,
    js.vendor_id,
    v.short_name AS vendor_name,
    v.company_name AS vendor_company,
    js.employee_id,
    e.short_name AS employee_name,
    COALESCE(v.short_name, e.short_name, 'Chưa gán'::character varying) AS assigned_to,
        CASE
            WHEN (js.vendor_id IS NOT NULL) THEN 'VENDOR'::text
            WHEN (js.employee_id IS NOT NULL) THEN 'EMPLOYEE'::text
            ELSE 'UNASSIGNED'::text
        END AS assignment_type,
    js.scheduled_date,
    js.scheduled_time,
    js.origin_address,
    js.dest_address,
    js.cargo_type,
    js.package_quantity,
    js.package_unit,
    js.weight_kg,
    js.dimension_length_cm,
    js.dimension_width_cm,
    js.dimension_height_cm,
    js.invoice_numbers,
    js.special_requirements,
    js.vendor_text_input,
    js.driver_id,
    js.vehicle_id,
    js.status_code,
    js.created_at,
    js.updated_at
   FROM (((((public.job_services js
     JOIN public.jobs j ON ((js.job_id = j.job_id)))
     JOIN public.customers c ON ((j.customer_id = c.customer_id)))
     LEFT JOIN public.vendors v ON ((js.vendor_id = v.vendor_id)))
     LEFT JOIN public.employees e ON ((js.employee_id = e.employee_id)))
     LEFT JOIN public.master_service_types mst ON (((js.service_type_code)::text = (mst.service_code)::text)))
  WHERE ((js.service_type_code)::text = ANY ((ARRAY['TRUCKING_SHORT'::character varying, 'TRUCKING_LONG'::character varying])::text[]));


ALTER VIEW public.v_trucking_services OWNER TO slms_admin;

--
-- Name: v_vendors; Type: VIEW; Schema: public; Owner: slms_admin
--

CREATE VIEW public.v_vendors AS
 SELECT vendor_id,
    vendor_code,
    company_name,
    short_name,
    tax_code,
    address,
    province,
    vendor_type,
    contact_name,
    contact_phone,
    telegram_chat_id,
    bank_name,
    bank_account,
    payment_terms,
    is_active,
    created_at
   FROM public.vendors
  WHERE (is_active = true)
  ORDER BY company_name;


ALTER VIEW public.v_vendors OWNER TO slms_admin;

--
-- Name: v_warehouse_services; Type: VIEW; Schema: public; Owner: slms_admin
--

CREATE VIEW public.v_warehouse_services AS
 SELECT js.svc_id,
    js.job_id,
    j.job_no,
    js.service_type_code,
    mst.name_vi AS service_name,
    c.short_name AS customer,
    c.customer_code,
    js.vendor_id,
    v.short_name AS vendor_name,
    js.employee_id,
    e.short_name AS employee_name,
    COALESCE(v.short_name, e.short_name, 'Chưa gán'::character varying) AS assigned_to,
        CASE
            WHEN (js.vendor_id IS NOT NULL) THEN 'VENDOR'::text
            WHEN (js.employee_id IS NOT NULL) THEN 'EMPLOYEE'::text
            ELSE 'UNASSIGNED'::text
        END AS assignment_type,
    js.scheduled_date,
    js.origin_address AS warehouse_location,
    js.cargo_type,
    js.package_quantity,
    js.weight_kg,
    js.volume_cbm,
    js.storage_start_date,
    js.storage_end_date,
    js.status_code,
    js.created_at
   FROM (((((public.job_services js
     JOIN public.jobs j ON ((js.job_id = j.job_id)))
     JOIN public.customers c ON ((j.customer_id = c.customer_id)))
     LEFT JOIN public.vendors v ON ((js.vendor_id = v.vendor_id)))
     LEFT JOIN public.employees e ON ((js.employee_id = e.employee_id)))
     LEFT JOIN public.master_service_types mst ON (((js.service_type_code)::text = (mst.service_code)::text)))
  WHERE ((js.service_type_code)::text = ANY ((ARRAY['WHS_STORAGE'::character varying, 'WHS_HANDLE'::character varying, 'WHS_VAS'::character varying])::text[]));


ALTER VIEW public.v_warehouse_services OWNER TO slms_admin;

