--
-- Name: view_customer_surcharges; Type: VIEW; Schema: public; Owner: slms_admin
--

CREATE VIEW public.view_customer_surcharges AS
 SELECT cs.id,
    c.customer_code,
    c.short_name AS customer_name,
    cs.surcharge_code,
    cs.surcharge_name,
    csp.vehicle_type,
    csp.price,
    cs.free_allowance,
    cs.unit,
    cs.effective_date,
    cs.notes
   FROM ((public.customer_surcharges cs
     JOIN public.customers c ON ((cs.customer_id = c.customer_id)))
     LEFT JOIN public.customer_surcharge_prices csp ON ((cs.id = csp.surcharge_id)))
  WHERE (cs.is_active = true)
  ORDER BY c.customer_code, cs.surcharge_code, csp.vehicle_type;


ALTER VIEW public.view_customer_surcharges OWNER TO slms_admin;

--
-- Name: view_ebook_selling_prices; Type: VIEW; Schema: public; Owner: slms_admin
--

CREATE VIEW public.view_ebook_selling_prices AS
 SELECT r.origin,
    r.destination,
    r.distance_km,
    p.vehicle_type_code,
    p.unit_price,
    p.notes
   FROM (public.master_prices p
     JOIN public.master_routes r ON ((p.route_id = r.route_id)))
  WHERE (((p.price_type)::text = 'STANDARD_SELLING'::text) AND (p.is_active = true));


ALTER VIEW public.view_ebook_selling_prices OWNER TO slms_admin;

--
-- Name: view_vendor_rates_full; Type: VIEW; Schema: public; Owner: slms_admin
--

CREATE VIEW public.view_vendor_rates_full AS
 SELECT vr.id,
    v.vendor_code,
    v.company_name AS vendor_name,
    v.short_name AS vendor_short_name,
    mr.origin,
    vr.origin_province,
    mr.destination,
    vr.destination_province,
    vr.rate_code,
    vr.rate_type,
    vr.vehicle_type,
    vr.temperature_range,
    vr.price,
    vr.notes,
    vr.effective_date,
    vr.is_active
   FROM ((public.vendor_rates vr
     JOIN public.vendors v ON ((vr.vendor_id = v.vendor_id)))
     LEFT JOIN public.master_routes mr ON ((vr.route_id = mr.route_id)))
  WHERE (vr.is_active = true)
  ORDER BY v.vendor_code, mr.origin, mr.destination, vr.vehicle_type;


ALTER VIEW public.view_vendor_rates_full OWNER TO slms_admin;

--
-- Name: view_vendor_surcharges; Type: VIEW; Schema: public; Owner: slms_admin
--

CREATE VIEW public.view_vendor_surcharges AS
 SELECT vs.id,
    v.vendor_code,
    v.short_name AS vendor_name,
    vs.surcharge_code,
    vs.surcharge_name,
    vs.rate_type,
    vsp.vehicle_type,
    vsp.price,
    vs.free_allowance,
    vs.unit,
    vs.effective_date,
    vs.notes
   FROM ((public.vendor_surcharges vs
     JOIN public.vendors v ON ((vs.vendor_id = v.vendor_id)))
     LEFT JOIN public.vendor_surcharge_prices vsp ON ((vs.id = vsp.surcharge_id)))
  WHERE (vs.is_active = true)
  ORDER BY v.vendor_code, vs.surcharge_code, vsp.vehicle_type;


